documents = {"setup": "Create a virtual environment before installing packages.",
             "splits": "Keep the final test set separate from model selection."}
def retrieve(question):
    query = set(question.lower().strip("?.!").split())
    ranked = sorted(documents, key=lambda key: -len(query & set(documents[key].lower().split())))
    best = ranked[0]
    overlap = len(query & set(documents[best].lower().split()))
    return {"source_id": best, "passage": documents[best]} if overlap else {"status": "no_match"}
print(retrieve("Why keep a test set separate?"))
print(retrieve("Galactic weather tomorrow?"))
